import * as React from "react";
import { cx } from "./cx";
import { Calendar } from "./calendar";

export interface DatePickerProps
  extends Omit<React.HTMLAttributes<HTMLDivElement>, "onChange" | "defaultValue"> {
  value?: Date;
  onChange?: (date: Date) => void;
  placeholder?: string;
  format?: (date: Date) => string;
}

const defaultDateFormat = (d: Date) =>
  d.toLocaleDateString("en", { day: "numeric", month: "long", year: "numeric" });

/** Hairline trigger with a calendar overlay. */
export function DatePicker({
  value,
  onChange,
  placeholder = "Pick a date",
  format = defaultDateFormat,
  className,
  ...props
}: DatePickerProps) {
  const rootRef = React.useRef<HTMLDivElement>(null);
  const [open, setOpen] = React.useState(false);

  React.useEffect(() => {
    if (!open) return;
    const onPointerDown = (e: PointerEvent) => {
      if (!rootRef.current?.contains(e.target as Node)) setOpen(false);
    };
    const onKey = (e: KeyboardEvent) => {
      if (e.key === "Escape") setOpen(false);
    };
    document.addEventListener("pointerdown", onPointerDown);
    document.addEventListener("keydown", onKey);
    return () => {
      document.removeEventListener("pointerdown", onPointerDown);
      document.removeEventListener("keydown", onKey);
    };
  }, [open]);

  return (
    <div ref={rootRef} className={cx("rs-select", className)} {...props}>
      <button
        type="button"
        className="rs-dropdown"
        aria-haspopup="dialog"
        aria-expanded={open}
        onClick={() => setOpen((o) => !o)}
      >
        <span>{value ? format(value) : placeholder}</span>
        <svg viewBox="0 0 16 16" width="16" height="16" fill="none" aria-hidden="true">
          <rect x="2.75" y="3.75" width="10.5" height="9.5" rx="1.5" stroke="currentColor" strokeWidth="1.5" />
          <path d="M2.75 6.75h10.5M5.5 2v2.5M10.5 2v2.5" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" />
        </svg>
      </button>
      {open && (
        <div className="rs-menu" style={{ padding: 12, right: "auto" }}>
          <Calendar
            value={value}
            onSelect={(d) => {
              onChange?.(d);
              setOpen(false);
            }}
          />
        </div>
      )}
    </div>
  );
}

import * as React from "react";
import { cx } from "./cx";
import { Icon } from "./icon";

export interface CalendarProps extends Omit<React.HTMLAttributes<HTMLDivElement>, "onSelect"> {
  value?: Date;
  onSelect?: (date: Date) => void;
  defaultMonth?: Date;
  /** 0 = Sunday, 1 = Monday. */
  weekStart?: 0 | 1;
}

const DOW = ["Mo", "Tu", "We", "Th", "Fr", "Sa", "Su"];

function sameDay(a: Date | undefined, b: Date): boolean {
  return (
    !!a && a.getFullYear() === b.getFullYear() && a.getMonth() === b.getMonth() && a.getDate() === b.getDate()
  );
}

/** Month grid. Selected is ink; today is a hairline. */
export function Calendar({ value, onSelect, defaultMonth, weekStart = 1, className, ...props }: CalendarProps) {
  const [month, setMonth] = React.useState(() => {
    const base = value ?? defaultMonth ?? new Date();
    return new Date(base.getFullYear(), base.getMonth(), 1);
  });

  const first = new Date(month.getFullYear(), month.getMonth(), 1);
  const lead = (first.getDay() - weekStart + 7) % 7;
  const start = new Date(month.getFullYear(), month.getMonth(), 1 - lead);
  const days = Array.from({ length: 42 }, (_, i) => {
    const d = new Date(start);
    d.setDate(start.getDate() + i);
    return d;
  });
  const today = new Date();
  const title = month.toLocaleDateString("en", { month: "long", year: "numeric" });
  const dows = weekStart === 1 ? DOW : ["Su", ...DOW.slice(0, 6)];
  const shift = (delta: number) => setMonth(new Date(month.getFullYear(), month.getMonth() + delta, 1));

  return (
    <div className={cx("rs-cal", className)} {...props}>
      <div className="rs-cal-head">
        <span className="rs-cal-title" aria-live="polite">
          {title}
        </span>
        <span className="rs-cal-nav">
          <button type="button" className="rs-page" aria-label="Previous month" onClick={() => shift(-1)}>
            <Icon name="chevron-left" size={12} />
          </button>
          <button type="button" className="rs-page" aria-label="Next month" onClick={() => shift(1)}>
            <Icon name="chevron-right" size={12} />
          </button>
        </span>
      </div>
      <div className="rs-cal-grid" role="grid">
        {dows.map((d) => (
          <span key={d} className="rs-cal-dow" role="columnheader">
            {d}
          </span>
        ))}
        {days.map((d) => {
          const out = d.getMonth() !== month.getMonth();
          const selected = sameDay(value, d);
          return (
            <button
              key={d.toISOString()}
              type="button"
              className={cx(
                "rs-cal-day",
                out && "rs-cal-day-out",
                sameDay(today, d) && "rs-cal-day-today",
                selected && "rs-cal-day-selected",
              )}
              aria-pressed={selected}
              aria-label={d.toDateString()}
              onClick={() => {
                onSelect?.(d);
                if (out) setMonth(new Date(d.getFullYear(), d.getMonth(), 1));
              }}
            >
              {d.getDate()}
            </button>
          );
        })}
      </div>
    </div>
  );
}

import * as React from "react";
import { cx } from "./cx";

/**
 * Raster chrome marks. Vera 28 Aug 2026.
 *
 * 16×16 module, optical center 8,8. Stroke 1, currentColor, fill none.
 * Cap butt, join miter, no rx. Hairline stays 1 CSS px at 12 and 16.
 * Copied is check. Accordion down is chevron-right rotated 90°.
 */
export const ICON_STROKE = 1;
export const ICON_VIEWBOX = 16;

export const iconInk = {
  fill: "none",
  stroke: "currentColor",
  strokeWidth: ICON_STROKE,
  strokeLinecap: "butt",
  strokeLinejoin: "miter",
  vectorEffect: "non-scaling-stroke",
} as const;

export const iconNames = ["copy", "copied", "chevron-left", "chevron-right", "close"] as const;
export type IconName = (typeof iconNames)[number] | "check";
export type IconSize = 12 | 16;
export type IconRotate = 90 | 180 | 270;

const marks: Record<(typeof iconNames)[number], React.ReactNode> = {
  copy: (
    <>
      <path d="M6.5 2.5 H13.5 V9.5" {...iconInk} />
      <rect x="2.5" y="6.5" width="7" height="7" {...iconInk} />
    </>
  ),
  copied: <path d="M3.5 8.5 L6.5 11.5 L12.5 4.5" {...iconInk} />,
  "chevron-left": <path d="M10.5 3.5 L5.5 8 L10.5 12.5" {...iconInk} />,
  "chevron-right": <path d="M5.5 3.5 L10.5 8 L5.5 12.5" {...iconInk} />,
  close: (
    <>
      <path d="M4.5 4.5 L11.5 11.5" {...iconInk} />
      <path d="M11.5 4.5 L4.5 11.5" {...iconInk} />
    </>
  ),
};

function resolveName(name: IconName): (typeof iconNames)[number] {
  return name === "check" ? "copied" : name;
}

export interface IconProps extends Omit<React.SVGAttributes<SVGSVGElement>, "children" | "rotate"> {
  name: IconName;
  size?: IconSize;
  /** Same mark, spun around 8,8. Accordion down is chevron-right at 90. */
  rotate?: IconRotate;
}

/** One mark. Size is the drawn square; the viewBox is always 16. */
export function Icon({ name, size = 16, rotate, className, ...props }: IconProps) {
  const nodes = marks[resolveName(name)];
  return (
    <svg
      className={cx("rs-icon", className)}
      viewBox="0 0 16 16"
      width={size}
      height={size}
      aria-hidden="true"
      {...iconInk}
      {...props}
    >
      {rotate ? <g transform={`rotate(${rotate} 8 8)`}>{nodes}</g> : nodes}
    </svg>
  );
}

/** Join class names, dropping falsy parts. */
export function cx(...parts: Array<string | false | null | undefined>): string {
  return parts.filter(Boolean).join(" ");
}

/* ── Dropdown + menu: the menu overlays, it never pushes layout ── */
.rs-select{position:relative;display:inline-block;min-width:180px}
.rs-select .rs-menu{position:absolute;top:100%;left:0;right:0;z-index:50;margin-top:6px}
.rs-dropdown{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:9px 12px;border:1px solid var(--divider);border-radius:var(--radius-sm);font-size:14px;color:var(--text);letter-spacing:-.01em}
button.rs-dropdown{cursor:pointer;font-family:inherit;background:none;width:100%}
.rs-menu{border:1px solid var(--divider);border-radius:var(--radius-sm);margin-top:6px;overflow:hidden;background:var(--bg);box-shadow:0 8px 24px rgba(0,0,0,0.06)}
.rs-menu-item{display:block;padding:9px 12px;font-size:14px;color:var(--text);letter-spacing:-.01em;border-bottom:1px solid var(--divider)}
.rs-menu-item:last-child{border-bottom:none}
.rs-menu-item.rs-menu-item-active,button.rs-menu-item-active{background:var(--divider-subtle)}
button.rs-menu-item{width:100%;text-align:left;cursor:pointer;background:none;border-left:none;border-right:none;border-top:none;font-family:inherit}

/* ── Calendar: a month of quiet squares; selected is ink ── */
.rs-cal{width:252px}
.rs-cal-head{display:flex;justify-content:space-between;align-items:center;min-height:26px;margin-bottom:8px}
.rs-cal-title{font-size:13px;font-weight:600;letter-spacing:-.01em;line-height:26px;color:var(--text)}
.rs-cal-nav{display:flex;gap:5px}
/* Inter ‹ › sit high in the em; the 26px nav chrome reads ~1px above the title ink. */
.rs-cal-nav .rs-page{transform:translateY(1px)}
.rs-cal-grid{display:grid;grid-template-columns:repeat(7,36px)}
.rs-cal-dow{font-size:11px;font-weight:500;color:var(--text-secondary);text-align:center;padding:4px 0}
.rs-cal-day{width:36px;height:36px;display:flex;align-items:center;justify-content:center;font-size:13px;font-variant-numeric:tabular-nums;color:var(--text);background:none;border:none;border-radius:var(--radius-sm);cursor:pointer;font-family:inherit;padding:0}
.rs-cal-day:hover{background:var(--divider-subtle)}
.rs-cal-day-out{color:var(--text-secondary);opacity:.45}
.rs-cal-day-today{box-shadow:inset 0 0 0 1px var(--divider)}
.rs-cal-day-selected,.rs-cal-day-selected:hover{background:var(--text);color:var(--bg);font-weight:600}
